SELECT qryInvoiceRPT1.CaseID, [Last_Name] & ", " & [First_Name] AS Name, qryInvoiceRPT1.First_Name, qryInvoiceRPT1.Last_Name, qryInvoiceRPT1.Retainer, Sum(qryInvoiceRPT1.Charge) AS SumOfCharge, Sum(qryInvoiceRPT1.Payment) AS SumOfPayment, Sum(qryInvoiceRPT1.Balance) AS SumOfBalance, Sum([charge]-[payment]) AS BalanceCalculated, [BalanceCalculated]+[qryInvoiceRPT1].[Retainer] AS BalRetCalculated, qryInvoiceRPT1.Spanish, Replace([Case_Letter] & [yr] & "-" & [Number_] & "-" & [Orig_Atty],"__","_") AS FileNumber, qryInvoiceRPT1.[Balance Due Date], qryInvoiceRPT1.Orig_Atty, qryInvoiceRPT1.HandlingAtty_Case, tblDropD.CodeVal, qryInvoiceRPT1.Executor, qryInvoiceRPT1.Case_Letter
FROM qryInvoiceRPT1 LEFT JOIN tblDropD ON qryInvoiceRPT1.Case_Letter = tblDropD.Code
GROUP BY qryInvoiceRPT1.CaseID, [Last_Name] & ", " & [First_Name], qryInvoiceRPT1.First_Name, qryInvoiceRPT1.Last_Name, qryInvoiceRPT1.Retainer, qryInvoiceRPT1.Spanish, Replace([Case_Letter] & [yr] & "-" & [Number_] & "-" & [Orig_Atty],"__","_"), qryInvoiceRPT1.[Balance Due Date], qryInvoiceRPT1.Orig_Atty, qryInvoiceRPT1.HandlingAtty_Case, tblDropD.CodeVal, qryInvoiceRPT1.Executor, qryInvoiceRPT1.Case_Letter
HAVING (((qryInvoiceRPT1.Case_Letter)<>"P" And (qryInvoiceRPT1.Case_Letter)<>"B"))
ORDER BY qryInvoiceRPT1.[Balance Due Date] DESC;